                       FROM public.attested_training(d, '1900-01-01'::timestamptz, '2200-01-01'::timestamptz) a),
        'iso', (SELECT md5(coalesce(string_agg(h.member_id || '|' || h.training_hours || '|' || h.standby_hours || '|' || h.iso_total_hours, ',' ORDER BY h.member_id), ''))
