        raise exception ''NOT_PRESENT: only members on the session''''s roll can react.'';
      end if;
      if (now() at time zone ''America/Chicago'')::date - s."date" > 14 then
        raise exception ''CLOSED: reactions close 14 days after the session.'';
      end if;
      insert into public.training_session_reactions as r (department_id, session_id, member_id, value)
      values (s.department_id, s.id, v_me, p_value)
      on conflict (session_id, member_id) do update set value = excluded.value, updated_at = now()
      returning r.* into v_row;
      return jsonb_build_object(''session_id'', v_row.session_id, ''value'', v_row.value, ''updated_at'', v_row.updated_at);
    end;
' AND p.prosecdef AND p.provolatile = 'v' AND p.proconfig = ARRAY['search_path=public']
             AND coalesce(p.proacl::text, '') = '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' AND NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND p.pronargdefaults = 0
        FROM pg_proc p WHERE p.oid = to_regprocedure('public.set_session_reaction(uuid, integer)')), false) THEN
    RAISE EXCEPTION 'Post-condition failed: set_session_reaction is not the generated body / SECURITY DEFINER / search_path=public / authenticated + service_role only (anon must not execute). Rolling back.';
  END IF;
  IF NOT coalesce((SELECT p.prosrc = '
    -- B4C:E1E3 slice R — leadership''s view of the reactions: COUNTS ONLY, never who. is_leader() (PA / DA / Board / Officer in
    -- the caller''s active department). Counts only votes from members STILL on the session''s roll (someone removed via Correct
    -- drops out), only sessions in the caller''s department (any other id returns nothing), and a session returns NO row until
    -- it has at least 3 counted votes — so a small session can''t be de-anonymised. Enforced here, so the API can''t bypass it.
    declare v_dept uuid := public.my_department_id();
    begin
      if v_dept is null or not public.is_leader() then
        raise exception ''NOT_ALLOWED: only department leadership can see reaction tallies.'';
      end if;
      return query
        select r.session_id,
               (count(*) filter (where r.value = 1))::integer,
               (count(*) filter (where r.value = -1))::integer
          from public.training_session_reactions r
          join public.training_sessions ts on ts.id = r.session_id and ts.department_id = v_dept
         where r.session_id = any (p_session_ids)
           and r.department_id = v_dept
           and exists (select 1 from public.session_attendance a where a.session_id = r.session_id and a.member_id = r.member_id)
         group by r.session_id
        having count(*) >= 3;
    end;
' AND p.prosecdef AND p.provolatile = 's' AND p.proconfig = ARRAY['search_path=public']
             AND coalesce(p.proacl::text, '') = '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' AND NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND p.pronargdefaults = 0
        FROM pg_proc p WHERE p.oid = to_regprocedure('public.session_reaction_tally(uuid[])')), false) THEN
    RAISE EXCEPTION 'Post-condition failed: session_reaction_tally is not the generated body / STABLE SECURITY DEFINER / search_path=public / authenticated + service_role only (anon must not execute). Rolling back.';
  END IF;
  -- nothing else
  IF md5(pg_get_functiondef('public.tg_training_session_lock_guard()'::regprocedure)) IS DISTINCT FROM 'c1af95df40d551b75998cde0a8f290f7' OR md5(pg_get_functiondef('public.correct_training_session(uuid, jsonb, uuid[], uuid[], text)'::regprocedure)) IS DISTINCT FROM '8c00066509e9dca338dc3662f55e1211'
     OR md5(pg_get_functiondef('public.attested_training(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)) IS DISTINCT FROM 'aff25333771cd38c1f473bcde5e1e96e' OR md5(pg_get_functiondef('public.dept_iso_hours_for(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)) IS DISTINCT FROM '705c9a9b5532d28824f5e50e74d6059f' THEN
    RAISE EXCEPTION 'Post-condition failed: the guard / correct / attested_training / dept_iso_hours_for changed. Rolling back.';
  END IF;
  IF (SELECT md5(string_agg(md5(pg_get_functiondef(p.oid)) || coalesce(p.proacl::text, ''), ',' ORDER BY p.oid::regprocedure::text)) FROM pg_proc p
       WHERE p.pronamespace = 'public'::regnamespace AND p.prokind = 'f' AND p.oid::regprocedure::text NOT IN ('set_session_reaction(uuid,integer)', 'session_reaction_tally(uuid[])')) IS DISTINCT FROM v_others THEN RAISE EXCEPTION 'Post-condition failed: another public function changed. Rolling back.'; END IF;
  IF (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND prokind = 'f') <> v_fn_n + 2 THEN RAISE EXCEPTION 'Post-condition failed: the function count is not +2. Rolling back.'; END IF;
  IF (SELECT md5(string_agg(tablename || '|' || policyname || '|' || cmd || '|' || roles::text || '|' || coalesce(qual, '') || '|' || coalesce(with_check, ''), ',' ORDER BY tablename, policyname)) FROM pg_policies WHERE schemaname = 'public' AND tablename <> 'training_session_reactions') IS DISTINCT FROM 'a9947383b4635e2e54fa89fa81947fc9' OR (SELECT count(*) FROM pg_policies WHERE schemaname = 'public') <> v_pol_n + 1 THEN
    RAISE EXCEPTION 'Post-condition failed: another policy changed, or the policy count is not +1. Rolling back.';
  END IF;
  IF (SELECT count(*) FROM pg_class WHERE relnamespace = 'public'::regnamespace AND relkind IN ('r', 'p', 'v', 'm')) <> v_rel_n + 1 THEN RAISE EXCEPTION 'Post-condition failed: the relation count is not +1. Rolling back.'; END IF;
  IF (SELECT md5(string_agg(c.relname || '.' || t.tgname || '|' || pg_get_triggerdef(t.oid), ',' ORDER BY (c.relname || '.' || t.tgname) COLLATE "C")) FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid WHERE t.tgrelid IN ('public.training_sessions'::regclass, 'public.session_attendance'::regclass) AND NOT t.tgisinternal) IS DISTINCT FROM '0e2714dae8ca4600780ea7c49eaf7059' OR (SELECT md5(string_agg(c.relname || '.' || k.conname || '|' || pg_get_constraintdef(k.oid), ',' ORDER BY (c.relname || '.' || k.conname) COLLATE "C")) FROM pg_constraint k JOIN pg_class c ON c.oid = k.conrelid WHERE k.conrelid IN ('public.training_sessions'::regclass, 'public.session_attendance'::regclass) AND k.contype <> 'n') IS DISTINCT FROM '25511204a6c5038b46056c2504be9b99' THEN
    RAISE EXCEPTION 'Post-condition failed: a training_sessions / session_attendance trigger or constraint changed. Rolling back.';
  END IF;
  IF (SELECT count(*) FROM public.station_presence WHERE verified) <> v_ver THEN RAISE EXCEPTION 'Post-condition failed: verified presence changed. Rolling back.'; END IF;
END
$migrate$;

NOTIFY pgrst, 'reload schema';

-- ---------------------------------------------------------------- state row
SELECT jsonb_build_object(
  'table_columns', (SELECT string_agg(column_name || ':' || udt_name || ':' || is_nullable || ':' || coalesce(column_default, ''), ',' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'training_session_reactions'),
  'table_constraints', (SELECT string_agg(k.contype::text || ':' || coalesce((SELECT string_agg(a.attname, ',' ORDER BY u.ord) FROM unnest(k.conkey) WITH ORDINALITY u(n, ord) JOIN pg_attribute a ON a.attrelid = k.conrelid AND a.attnum = u.n), '')
         || ':' || CASE WHEN k.contype = 'f' THEN (SELECT relname FROM pg_class WHERE oid = k.confrelid) ELSE '' END || ':' || CASE WHEN k.contype = 'f' THEN k.confdeltype::text ELSE '' END,
         ';' ORDER BY (k.contype::text || ':' || coalesce((SELECT string_agg(a.attname, ',' ORDER BY u.ord) FROM unnest(k.conkey) WITH ORDINALITY u(n, ord) JOIN pg_attribute a ON a.attrelid = k.conrelid AND a.attnum = u.n), '')) COLLATE "C")
     FROM pg_constraint k WHERE k.conrelid = 'public.training_session_reactions'::regclass AND k.contype <> 'n'),
  'rls', (SELECT relrowsecurity FROM pg_class WHERE oid = 'public.training_session_reactions'::regclass),
  'policies_on_table', (SELECT jsonb_agg(jsonb_build_object('name', policyname, 'cmd', cmd, 'roles', roles::text, 'qual', qual, 'check', with_check)) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'training_session_reactions'),
  'privileges', jsonb_build_object(
     'authenticated', (SELECT string_agg(p, ',' ORDER BY p) FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p WHERE has_table_privilege('authenticated', 'public.training_session_reactions', p)),
     'anon', coalesce((SELECT string_agg(p, ',' ORDER BY p) FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p WHERE has_table_privilege('anon', 'public.training_session_reactions', p)), '(none)')),
  'rows', (SELECT count(*) FROM public.training_session_reactions),
  'set_session_reaction', (SELECT jsonb_build_object('md5', md5(pg_get_functiondef(p.oid)), 'secdef', p.prosecdef, 'acl', p.proacl::text, 'anon_exec', has_function_privilege('anon', p.oid, 'EXECUTE')) FROM pg_proc p WHERE p.oid = 'public.set_session_reaction(uuid, integer)'::regprocedure),
  'session_reaction_tally', (SELECT jsonb_build_object('md5', md5(pg_get_functiondef(p.oid)), 'secdef', p.prosecdef, 'volatile', p.provolatile, 'acl', p.proacl::text, 'anon_exec', has_function_privilege('anon', p.oid, 'EXECUTE')) FROM pg_proc p WHERE p.oid = 'public.session_reaction_tally(uuid[])'::regprocedure),
  'guard_md5', md5(pg_get_functiondef('public.tg_training_session_lock_guard()'::regprocedure)), 'correct_md5', md5(pg_get_functiondef('public.correct_training_session(uuid, jsonb, uuid[], uuid[], text)'::regprocedure)), 'attested_md5', md5(pg_get_functiondef('public.attested_training(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)), 'iso_md5', md5(pg_get_functiondef('public.dept_iso_hours_for(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)),
  'fn_count', (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND prokind = 'f'),
  'total_policies', (SELECT count(*) FROM pg_policies WHERE schemaname = 'public'),
  'verified_presence', (SELECT count(*) FROM public.station_presence WHERE verified)
) AS state;
